from fractions import Fraction

def reduce_fraction(decimal_str, repeat_len):
    non_repeating, repeating = decimal_str.split('.')
    non_repeating_int = int(non_repeating)
    repeating_int = int(repeating[:repeat_len])

    num_length = len(non_repeating + repeating[:repeat_len])
    den_length = len(repeating)

    if num_length > den_length:
        return str(Fraction(non_repeating_int * (10 ** den_length) + repeating_int - non_repeating_int, 10 ** den_length - 1))
    else:
        return str(Fraction(non_repeating_int * (10 ** den_length) + repeating_int - non_repeating_int, 10 ** den_length - 1))

# Example usage
import sys
input = sys.stdin.read().strip()
decimal_str, repeat_len = input.split()
print(reduce_fraction(decimal_str, int(repeat_len)))
